INSERT INTO temp_import_pages VALUES ('{"pageId": "c0330000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "sourceShowsPrintedPageLabel": true, "printedPageLabel": "33", "printedPageNumber": 33, "pdfPageNumber": 416, "sequenceIndex": 23, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true, "provenanceNotes": "Canonical transcription checked against the rendered secondary scan; master PDF page mapping retained. Fine vocalisation is preserved where clearly legible; no unresolved Arabic word or letter remains. English OCR correction and Arabic/translation-pair classification pass compared against the rendered source scan; raw OCR retained unchanged."}, "structuralNodes": [{"id": "a6000000-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "PART I", "sourceIdentifier": "I", "title": "IMPORTANCE OF SALAAT", "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "a6100000-0000-4000-8000-000000000002", "parentId": "a6000000-0000-4000-8000-000000000001", "nodeType": "chapter", "sourceLabel": "CHAPTER.—II", "sourceIdentifier": "II", "title": "WARNING AND REPROACH FOR NEGLECTING SALAAT", "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "a6300000-0000-4000-8000-000000000001", "parentId": "a6100000-0000-4000-8000-000000000002", "nodeType": "hadith", "sourceLabel": "Hadith.—I", "sourceIdentifier": "I", "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}], "blocks": [{"id": "d0330000-0000-4000-8000-000000000001", "structuralNodeId": "a6100000-0000-4000-8000-000000000002", "sequenceIndex": 0, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "CHAPTER.—II", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0330000-0000-4000-8000-000000000002", "structuralNodeId": "a6100000-0000-4000-8000-000000000002", "sequenceIndex": 1, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "WARNING AND REPROACH FOR NEGLECTING SALAAT", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0330000-0000-4000-8000-000000000003", "structuralNodeId": "a6100000-0000-4000-8000-000000000002", "sequenceIndex": 2, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "The books on hadith mention very severe punishment for those who neglect salaat. From many traditions on the subject, only a few are reproduced in this chapter. Although a single warning from the most truthful Prophet (Sallallaho alaihe wasallam) was enough, yet we find that, out of love and mercy for his followers, he has cautioned them again and again and in various manners lest they should neglect salaat and suffer the consequences. In spite of all this, alas! we are unmindful of salaat, and still we have the audacity to consider ourselves devotees of the Prophet (Sallallaho alaihe wasallam) and champions of Islam.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0330000-0000-4000-8000-000000000004", "structuralNodeId": "a6300000-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith.—I", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0330000-0000-4000-8000-000000000005", "structuralNodeId": "a6300000-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ رَسُولُ اللَّهِ ﷺ بَيْنَ الرَّجُلِ وَبَيْنَ الْكُفْرِ تَرْكُ الصَّلَاةِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0330000-0000-4000-8000-000000000006", "structuralNodeId": "a6300000-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "رواه أحمد ومسلم وقال بين الرجل وبين الشرك والكفر ترك الصلاة رواه أبو داود والنسائي ولفظه ليس بين العبد وبين الكفر إلا ترك الصلاة والترمذي ولفظه قال بين الكفر والإيمان ترك الصلاة وابن ماجه ولفظه قال بين العبد وبين الكفر ترك الصلاة كذا في الترغيب للمنذري وقال السيوطي في الدر حديث جابر وغيره", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0330000-0000-4000-8000-000000000007", "structuralNodeId": "a6300000-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Jaabir bin Abdullah (Radhiyallaho anho) narrates that he heard the Prophet of Allah (Sallallaho alaihe wasallam) saying: 1. \"To discard salaat is to be linked with Kufr.\" 2. \"To discard salaat is to be linked with Kufr and Shirk.\" 3. \"Discarding of salaat is the only partition between Imaan and Kufr. \" There are a number of ahaadith on the subject. On one occasion, the Holy Prophet (Sallallaho alaihe wasallam) is reported to have said: \"Hurry up with your salaat when it", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}], "pageNumber": 33}'::jsonb);
